    21	
    22	struct Buffer {
    23	  const uint8_t *buf;
    24	  size_t len;
    25	};
    26	
    27	ssize_t reader_callback(struct archive *a, void *client_data,
    28	                        const void **block) {
    29	  Buffer *buffer = reinterpret_cast<Buffer *>(client_data);
    30	  *block = buffer->buf;
    31	  ssize_t len = buffer->len;
    32	  buffer->len = 0;
    33	  return len;
    34	}
    35	
    36	extern "C" int LLVMFuzzerTestOneInput(const uint8_t *buf, size_t len) {
    37	  ssize_t r;
    38	  struct archive *a = archive_read_new();
    39	
    40	  archive_read_support_filter_all(a);
    41	  archive_read_support_format_all(a);
    42	
    43	  Buffer buffer = {buf, len};
    44	  archive_read_open(a, &buffer, NULL, reader_callback, NULL);
    45	
    46	  std::vector<uint8_t> data_buffer(getpagesize(), 0);
    47	  struct archive_entry *entry;
    48	  while (archive_read_next_header(a, &entry) == ARCHIVE_OK) {
    49	    while ((r = archive_read_data(a, data_buffer.data(),
    50	            data_buffer.size())) > 0)
    51	      ;
    52	    if (r == ARCHIVE_FATAL)
    53	      break;
    54	  }
    55	
    56	  archive_read_free(a);
    57	  return 0;
    58	}
